-- ---------- The Lumière Tour (the-lumiere-tour, PUBLISHED) ----------
values (
  'ca25a3ff-cc04-5db4-b162-84aaf1e131c6', 'the-lumiere-tour', 'The Lumière Tour', 'music',
  '2026-10-24T19:00:00+07:00'::timestamptz, '2026-10-24T22:30:00+07:00'::timestamptz, 'PUBLISHED',
  $j${"name":"Sân vận động Quốc gia Mỹ Đình","city":"Hà Nội","address":"Đường Lê Đức Thọ, Nam Từ Liêm, Hà Nội"}$j$::jsonb,
  'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1600&q=80', 'Đám đông giơ tay trước sân khấu trong đêm nhạc', 'Hành trình âm nhạc bùng nổ với dàn sản xuất quốc tế và sân khấu 360 độ.',
  $j$["The Lumière Tour là chuỗi đêm diễn lớn nhất năm 2026, đưa toàn bộ ekip sản xuất từ chặng châu Âu về Hà Nội. Sân khấu dựng theo mô hình 360 độ với hệ thống đèn kinetic và màn LED bao quanh khán đài.","Chương trình kéo dài 3 tiếng 30 phút, gồm hai phần trình diễn chính và một khách mời đặc biệt sẽ được công bố trước đêm diễn một tuần.","Vé được phát hành dưới dạng vé điện tử gắn với tài khoản của bạn. Cổng mở lúc 17:00, khuyến khích đến sớm để tránh ùn tắc khu vực soát vé."]$j$::jsonb,
  $j$[{"time":"17:00","title":"Mở cổng"},{"time":"19:00","title":"Khai mạc, khách mời mở màn"},{"time":"20:00","title":"Phần 1: Lumière"},{"time":"21:15","title":"Phần 2: Afterglow"},{"time":"22:30","title":"Kết thúc"}]$j$::jsonb,
  (select id from organizers where slug = 'sunrise-live'), true,
  least(now(), '2026-10-24T19:00:00+07:00'::timestamptz) - interval '60 days'
) on conflict (slug) do nothing;

